// Cloudflare Worker entry.
// - /api/*  → the GtaHub Durable Object: the whole API runs there, next to its SQLite storage.
// - else    → the Next.js app built by OpenNext (`.open-next/worker.js`, generated at build time).
import { DurableObject } from "cloudflare:workers";
import { loadConfig, migrate } from "@gta/core";
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- generated by `opennextjs-cloudflare build`
// @ts-ignore -- no type declarations for the generated file
import { default as nextHandler } from "./.open-next/worker.js";
import { handleApi } from "./src/server/api";
import { DoSqlDatabase } from "./src/server/do-sql";
import { ServerState } from "./src/server/state";
import { loadWebConfig } from "./src/server/webconfig";

interface Env {
  GTA_HUB: DurableObjectNamespace<GtaHub>;
  [key: string]: unknown;
}

/** Free plan: 50 outgoing requests per invocation. Leave room for the rest of the request. */
const SYNC_RPC_BUDGET = 40;

/** The one place all API state lives: sessions, contacts, books, quotas (SQLite inside). */
export class GtaHub extends DurableObject<Env> {
  private readonly state: ServerState;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    const vars: Record<string, string | undefined> = {};
    for (const [k, v] of Object.entries(env)) if (typeof v === "string") vars[k] = v;
    const db = new DoSqlDatabase(ctx.storage);
    migrate(db);
    this.state = new ServerState({
      config: loadConfig(vars),
      web: loadWebConfig(vars as NodeJS.ProcessEnv),
      db,
      maxSyncRpcCalls: SYNC_RPC_BUDGET,
    });
  }

  override async fetch(request: Request): Promise<Response> {
    return handleApi(request, this.state);
  }
}

/** workers.dev and www go to the one canonical address. 308 keeps the method and body. */
function canonicalRedirect(request: Request, env: Env): Response | null {
  const canonical = typeof env.CANONICAL_HOST === "string" ? env.CANONICAL_HOST : "";
  if (!canonical) return null;
  const url = new URL(request.url);
  if (url.hostname === canonical) return null;
  if (!url.hostname.endsWith(".workers.dev") && url.hostname !== `www.${canonical}`) return null;
  url.protocol = "https:";
  url.hostname = canonical;
  url.port = "";
  return Response.redirect(url.toString(), 308);
}

const worker = {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const redirect = canonicalRedirect(request, env);
    if (redirect) return redirect;
    const url = new URL(request.url);
    if (url.pathname === "/api" || url.pathname.startsWith("/api/")) {
      const hub = env.GTA_HUB.get(env.GTA_HUB.idFromName("main"));
      return hub.fetch(request);
    }
    return nextHandler.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<Env>;

export default worker;

// Durable Objects used by OpenNext's optional caching features (unused, exported for compatibility).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- generated at build time
// @ts-ignore -- no type declarations for the generated file
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
